test('invoiceTotals sums VAT from multiple lines with different rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const line1Total = 10 * 9500;
  const line2Total = 100 * 37;
  const subtotal = line1Total + line2Total;
  const vat1 = Math.round((line1Total * 21) / 100);
  const vat2 = Math.round((line2Total * 9) / 100);
  const totalVat = vat1 + vat2;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.vat, totalVat);
  assert.equal(totals.total, subtotal + totalVat);
});

