import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with the customer, date and lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 4 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
});

test('createInvoice normalizes and stores uppercase customer ID', () => {
  const r = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with whitespace', () => {
  const r = createInvoice({
    customerId: '  c-001  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice accepts mixed case customer ID', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
});

test('createInvoice sets default terms to NET30', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
});

test('createInvoice calculates NET14 due date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET14');
  assert.equal(r.value.dueDate, '2026-10-21');
});

test('createInvoice calculates NET30 due date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice calculates EOM due date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'EOM');
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice with EOM handles month boundaries', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2026-01-31');
});

test('createInvoice rejects invalid terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
