import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with the customer, date and lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 4 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
});

test('createInvoice normalizes and stores uppercase customer ID', () => {
  const r = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with whitespace', () => {
  const r = createInvoice({
    customerId: '  c-001  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice accepts mixed case customer ID', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
});

test('createInvoice sets default terms to NET30', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
});

test('createInvoice calculates NET14 due date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET14');
  assert.equal(r.value.dueDate, '2026-10-21');
});

test('createInvoice calculates NET30 due date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice calculates EOM due date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'EOM');
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice with EOM handles month boundaries', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2026-01-31');
});

test('createInvoice rejects invalid terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET45',
  });
  assert.deepEqual(r, { ok: false, error: 'TERMS_INVALID' });
});

test('applyVoucher applies a voucher to a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 10000 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.voucher.code, 'SAVE10');
  assert.equal(r2.value.voucher.amount, 10000);
});

test('applyVoucher rejects non-draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const r2 = issueInvoice(r.value, []);
  const r3 = applyVoucher(r2.value, { code: 'SAVE10', amount: 10000 });
  assert.deepEqual(r3, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher rejects duplicate vouchers', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 10000 });
  const r3 = applyVoucher(r2.value, { code: 'SAVE20', amount: 5000 });
  assert.deepEqual(r3, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher rejects zero amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 0 });
  assert.deepEqual(r2, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher rejects negative amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: -5000 });
  assert.deepEqual(r2, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher rejects non-integer amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 5000.5 });
  assert.deepEqual(r2, { ok: false, error: 'AMOUNT_INVALID' });
});

test('invoiceTotals includes voucher in total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 10000 });
  const totals = invoiceTotals(r2.value);
  assert.equal(totals.voucher, 10000);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - 10000);
});

test('applyVoucher does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });
  const original = r.value;
  applyVoucher(original, { code: 'SAVE10', amount: 10000 });
  assert.equal(original.voucher, undefined);
});

test('createInvoice copies product details into each line', () => {
